def _directory_order(record: Mapping[str, Any]) -> tuple[str, str]:
    """Return the directory's stable sort key: username, then employee_id."""

    return (str(record.get("username", "")), str(record.get("employee_id", "")))


def _public_records(records: Iterable[Mapping[str, Any]]) -> list[dict[str, Any]]:
    """Project records to public fields and place them in directory order."""

    return sorted(
        (public_account(record) for record in records),
        key=_directory_order,
    )


def list_accounts_by_department(department: str) -> list[dict[str, Any]]:
    """Return public account records for one exact department."""

    return _public_records(
        record
        for record in _load_accounts()
        if record.get("department") == department
    )


def list_accounts_by_host_group(host_group: str) -> list[dict[str, Any]]:
    """Return public account records assigned to one exact host group."""

    return _public_records(
        record
        for record in _load_accounts()
        if record.get("host_group") == host_group
    )


def count_accounts_by_department(department: str) -> int:
    """Return the number of accounts in one exact department."""

    return sum(
        1 for record in _load_accounts() if record.get("department") == department
    )
